def count_repeats_naive(xs):
    ops = 0
    repeated = set()
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            ops += 1
            if xs[i] == xs[j]:
                repeated.add(xs[i])
    return len(repeated), ops

def count_repeats_map(xs):
    ops = 0
    counts = {}
    for x in xs:
        ops += 1
        counts[x] = counts.get(x, 0) + 1
    return sum(1 for v in counts.values() if v > 1), ops

data = [4, 1, 7, 1, 9, 4, 4, 2, 7, 5, 1, 8]
print("n:", len(data))
print("repeated values:", count_repeats_naive(data)[0])
print("naive ops:", count_repeats_naive(data)[1])
print("map ops:", count_repeats_map(data)[1])

