def max_depth(s):
    openers = {'(': ')', '[': ']', '{': '}'}
    closers = {')': '(', ']': '[', '}': '{'}
    stack = []
    depth = 0
    for ch in s:
        if ch in openers:
            stack.append(ch)
            if len(stack) > depth:
                depth = len(stack)
        elif ch in closers:
            if stack and stack[-1] == closers[ch]:
                stack.pop()
            else:
                return -1
    return depth if not stack else -1

tests = ["(a[b]{c})", "([]{})", "((()))", "(a]b)", "abc"]
for t in tests:
    print(repr(t), "->", max_depth(t))

