from collections import deque

def window_maxes(xs, w):
    dq = deque()
    out = []
    for i, x in enumerate(xs):
        while dq and xs[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - w:
            dq.popleft()
        if i >= w - 1:
            out.append(xs[dq[0]])
    return out

nums = [4, 2, 7, 1, 9, 3, 6, 5]
print("window size:", 3)
print("maxes:", window_maxes(nums, 3))

