N = 1000
COST = {
    "list":   {"random_access": 1, "push_back": 1, "push_front": N, "search": N},
    "linked": {"random_access": N, "push_back": 1, "push_front": 1, "search": N},
    "deque":  {"random_access": N, "push_back": 1, "push_front": 1, "search": N},
}

def cost_of(structure, workload):
    table = COST[structure]
    return sum(table[op] * freq for op, freq in workload.items())

def recommend(workload):
    return min(COST, key=lambda s: cost_of(s, workload))

wl_a = {"random_access": 80, "search": 20}
wl_b = {"push_front": 70, "push_back": 30}
for name, wl in [("random-heavy", wl_a), ("front-heavy", wl_b)]:
    costs = {s: cost_of(s, wl) for s in COST}
    print(name, costs, "->", recommend(wl))

