def first_repeat(xs):
    seen = set()
    for x in xs:
        if x in seen:
            return x
        seen.add(x)
    return None

def only_in_first(a, b):
    return sorted(set(a) - set(b))

nums = [5, 3, 9, 3, 7, 5]
print("first repeat:", first_repeat(nums))
print("only in first:", only_in_first([1, 2, 3, 4], [3, 4, 5]))
print("distinct count:", len(set(nums)))

