def canonical_key(rec):
    return (rec["type"], round(rec["x"], 2), round(rec["y"], 2))

def dedup_records(records):
    seen = set()
    out = []
    for r in records:
        k = canonical_key(r)
        if k not in seen:
            seen.add(k)
            out.append(r["id"])
    return out

records = [
    {"id": "a", "type": "pin", "x": 1.001, "y": 2.0},
    {"id": "b", "type": "pin", "x": 1.004, "y": 2.0},
    {"id": "c", "type": "pin", "x": 3.0, "y": 4.0},
    {"id": "d", "type": "flag", "x": 1.0, "y": 2.0},
]
print("kept ids:", dedup_records(records))
print("key of a:", canonical_key(records[0]))
print("distinct keys:", len({canonical_key(r) for r in records}))

