def range_query(tree, lo, hi):
    out = []
    if tree is None:
        return out
    value, left, right = tree
    if value > lo:
        out += range_query(left, lo, hi)
    if lo <= value <= hi:
        out.append(value)
    if value < hi:
        out += range_query(right, lo, hi)
    return out

def floor_value(tree, x):
    best = None
    node = tree
    while node is not None:
        value, left, right = node
        if value == x:
            return value
        if value < x:
            best = value
            node = right
        else:
            node = left
    return best

bst = (5,
       (3, (2, None, None), (4, None, None)),
       (8, (6, None, None), (9, None, None)))
print("range [3,6]:", range_query(bst, 3, 6))
print("floor of 7:", floor_value(bst, 7))
print("floor of 1:", floor_value(bst, 1))

