END = "$"

def add_word(root, word):
    node = root
    for ch in word:
        node = node.setdefault(ch, {})
    node[END] = True

def walk_to(root, prefix):
    node = root
    for ch in prefix:
        if ch not in node:
            return None
        node = node[ch]
    return node

def completions(root, prefix):
    node = walk_to(root, prefix)
    out = []
    if node is None:
        return out
    def collect(n, acc):
        for ch in sorted(n):
            if ch == END:
                out.append(prefix + acc)
            else:
                collect(n[ch], acc + ch)
    collect(node, "")
    return out

root = {}
for w in ["car", "cart", "care", "cat", "dog"]:
    add_word(root, w)
print("under 'ca':", completions(root, "ca"))
print("under 'car':", completions(root, "car"))
print("under 'do':", completions(root, "do"))
print("under 'x':", completions(root, "x"))

