from collections import deque

def components(adj):
    seen = set()
    count = 0
    for start in adj:
        if start in seen:
            continue
        count += 1
        stack = [start]
        while stack:
            u = stack.pop()
            if u in seen:
                continue
            seen.add(u)
            for v in adj[u]:
                if v not in seen:
                    stack.append(v)
    return count

def shortest_path(adj, src, dst):
    prev = {src: None}
    q = deque([src])
    while q:
        u = q.popleft()
        if u == dst:
            break
        for v in sorted(adj[u]):
            if v not in prev:
                prev[v] = u
                q.append(v)
    if dst not in prev:
        return []
    path = []
    node = dst
    while node is not None:
        path.append(node)
        node = prev[node]
    return path[::-1]

adj = {0: {1, 2}, 1: {0, 3}, 2: {0, 3}, 3: {1, 2, 4}, 4: {3}, 5: {6}, 6: {5}}
print("components:", components(adj))
print("path 0->4:", shortest_path(adj, 0, 4))
print("path 0->6:", shortest_path(adj, 0, 6))

