def best_fit(req):
    if req.get("relationships"):
        return "graph"
    if req.get("prefix"):
        return "trie"
    if req.get("lifo"):
        return "stack"
    if req.get("fifo"):
        return "queue / deque"
    if req.get("repeated_extreme"):
        return "heap"
    if req.get("ordered") or req.get("range"):
        return "balanced tree / sorted list"
    if req.get("key_lookup"):
        return "hash map (dict)"
    if req.get("unique"):
        return "set"
    return "list / array"

profiles = {
    "undo history":    {"lifo": True},
    "task scheduler":  {"fifo": True},
    "spell suggest":   {"prefix": True},
    "top players":     {"repeated_extreme": True},
    "unique visitors": {"unique": True},
    "friend network":  {"relationships": True},
}
for name in profiles:
    print(name, "->", best_fit(profiles[name]))
